#!/usr/bin/env bash
# AGENT INSTRUCTIONS: If editing the file, ensure that your model name is included here.
# Generated by Anthropic Claude-Opus-5.5 via Claude Code.
#
# Writes /etc/turnserver.conf from turnserver.conf.template, filling in this server's
# current addresses and the relay secret. The coturn service runs it (as root) before
# every start, so a changed public IP is picked up by a restart or reboot.
set -euo pipefail

here=$(dirname "$(readlink -f "$0")")

# shellcheck disable=SC1091
. /etc/hermes-route/turn.env   # sets P2P_TURN_SECRET
[ -n "${P2P_TURN_SECRET:-}" ] || { echo "P2P_TURN_SECRET is not set in /etc/hermes-route/turn.env" >&2; exit 1; }

private_ip=""
public_ip=""
for _ in 1 2 3 4 5 6; do
  private_ip=$(ip -4 route get 1.1.1.1 2>/dev/null | awk '{for (i = 1; i <= NF; i++) if ($i == "src") print $(i + 1)}')
  # Ask the cloud metadata service first, then an outside service
  token=$(curl -s -m 2 -X PUT http://169.254.169.254/latest/api/token -H 'X-aws-ec2-metadata-token-ttl-seconds: 60' || true)
  public_ip=$(curl -s -m 2 -H "X-aws-ec2-metadata-token: $token" http://169.254.169.254/latest/meta-data/public-ipv4 || true)
  [[ "$public_ip" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]] || public_ip=$(curl -4 -s -m 5 https://checkip.amazonaws.com || true)
  [[ "$private_ip" =~ ^[0-9.]+$ && "$public_ip" =~ ^[0-9.]+$ ]] && break
  sleep 2   # the network may not be up yet right after boot
done
[[ "$private_ip" =~ ^[0-9.]+$ && "$public_ip" =~ ^[0-9.]+$ ]] || { echo "Could not work out this server's addresses" >&2; exit 1; }

# Behind address translation (as on AWS) the relay must be told its outside address
external_line="# no external-ip needed: this server has its public address directly"
[ "$public_ip" != "$private_ip" ] && external_line="external-ip=$public_ip/$private_ip"

tmp=$(mktemp)
sed -e "s|@PRIVATE_IP@|$private_ip|" -e "s|@EXTERNAL_IP_LINE@|$external_line|" -e "s|@SECRET@|$P2P_TURN_SECRET|" \
  "$here/turnserver.conf.template" > "$tmp"
install -m 640 -o root -g turnserver "$tmp" /etc/turnserver.conf
rm -f "$tmp"
echo "Wrote /etc/turnserver.conf (relay at $public_ip, local address $private_ip)"
